/**
 * Why a song stopped sounding.
 */

enum class EndReason {
    
    /**
     * It played to its end.
     */
    FINISHED,
    /**
     * The listener moved to another song, or loaded a new queue.
     */
    SKIPPED,
    /**
     * It could not be played on.
     */
    FAILED,
    STOPPED;

    


    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeEndReason: FfiConverterRustBuffer<EndReason> {
    override fun read(buf: ByteBuffer) = try {
        EndReason.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: EndReason) = 4UL

    override fun write(value: EndReason, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}







/**
 * The error the app sees from engine calls.
 */
sealed class EngineException: kotlin.Exception() {
    
    class Failed(
        
        val `kind`: ErrorKind, 
        
        val `detail`: kotlin.String
        ) : EngineException() {
        override val message
            get() = "kind=${ `kind` }, detail=${ `detail` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<EngineException> {
        override fun lift(error_buf: RustBuffer.ByValue): EngineException = FfiConverterTypeEngineError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeEngineError : FfiConverterRustBuffer<EngineException> {
    override fun read(buf: ByteBuffer): EngineException {
        

        return when(buf.getInt()) {
            1 -> EngineException.Failed(
                FfiConverterTypeErrorKind.read(buf),
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: EngineException): ULong {
        return when(value) {
            is EngineException.Failed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterTypeErrorKind.allocationSize(value.`kind`)
                + FfiConverterString.allocationSize(value.`detail`)
            )
        }
    }

    override fun write(value: EngineException, buf: ByteBuffer) {
        when(value) {
            is EngineException.Failed -> {
                buf.putInt(1)
                FfiConverterTypeErrorKind.write(value.`kind`, buf)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



/**
 * Something the app may want to know, sent to the listener in order.
 */
sealed class EngineEvent {
    
    /**
     * A song began to be heard.
     */
    data class TrackStarted(
        val `itemId`: kotlin.String, 
        val `index`: kotlin.UInt, 
        val `info`: app.winters.octo.audio.TrackInfo?) : EngineEvent()
        
    {
        

        companion object
    }
    
    data class TrackEnded(
        val `itemId`: kotlin.String, 
        val `reason`: app.winters.octo.audio.EndReason) : EngineEvent()
        
    {
        

        companion object
    }
    
    /**
     * One song ran into the next with no gap.
     */
    data class GaplessTransition(
        val `fromId`: kotlin.String, 
        val `toId`: kotlin.String) : EngineEvent()
        
    {
        

        companion object
    }
    
    data class CrossfadeStarted(
        val `fromId`: kotlin.String, 
        val `toId`: kotlin.String, 
        val `durationMs`: kotlin.ULong) : EngineEvent()
        
    {
        

        companion object
    }
    
    /**
     * Sound stopped for lack of data.
     */
    data class Buffering(
        val `itemId`: kotlin.String?) : EngineEvent()
        
    {
        

        companion object
    }
    
    /**
     * Sound is flowing again.
     */
    data class Ready(
        val `itemId`: kotlin.String?) : EngineEvent()
        
    {
        

        companion object
    }
    
    data class StateChanged(
        val `state`: app.winters.octo.audio.PlaybackState) : EngineEvent()
        
    {
        

        companion object
    }
    
    /**
     * The last song finished and nothing follows.
     */
    object QueueEnded : EngineEvent()
    
    
    data class Error(
        val `kind`: app.winters.octo.audio.ErrorKind, 
        val `message`: kotlin.String, 
        val `itemId`: kotlin.String?) : EngineEvent()
        
    {
        

        companion object
    }
    
    /**
     * Output moved to another device, or the device list changed under it.
     * `format` is what the device's stream runs at.
     */
    data class DeviceChanged(
        val `device`: app.winters.octo.audio.OutputDevice?, 
        val `format`: app.winters.octo.audio.OutputFormat?) : EngineEvent()
        
    {
        

        companion object
    }
    
    /**
     * Sent at the interval asked for with `set_position_interval`.
     */
    data class Position(
        val `itemId`: kotlin.String, 
        val `positionMs`: kotlin.Double) : EngineEvent()
        
    {
        

        companion object
    }
    
    /**
     * A live stream's title changed, as it is heard: usually "Artist -
     * Song" for what the station plays now, as the station sent it. An
     * empty title says the stream no longer names what it plays. `url` is
     * the address sent with it (`StreamArtwork`, else `StreamUrl`), empty
     * when there is none.
     */
    data class StreamTitle(
        val `itemId`: kotlin.String, 
        val `title`: kotlin.String, 
        val `url`: kotlin.String) : EngineEvent()
        
    {
        

        companion object
    }
    
    /**
     * How the next song will follow the playing one, decided ahead of
     * time. `start_ms` is when in `from_id` the blend starts (its length
     * for a gapless join), `entry_ms` where `to_id` comes in, and
     * `overlap_ms` how long both sound, 0 for a gapless join. `reason` is a
     * line for the log, starting `automix:`.
     */
    data class TransitionPlanned(
        val `fromId`: kotlin.String, 
        val `toId`: kotlin.String, 
        val `startMs`: kotlin.ULong, 
        val `entryMs`: kotlin.ULong, 
        val `overlapMs`: kotlin.ULong, 
        val `reason`: kotlin.String) : EngineEvent()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeEngineEvent : FfiConverterRustBuffer<EngineEvent>{
    override fun read(buf: ByteBuffer): EngineEvent {
        return when(buf.getInt()) {
            1 -> EngineEvent.TrackStarted(
                FfiConverterString.read(buf),
                FfiConverterUInt.read(buf),
                FfiConverterOptionalTypeTrackInfo.read(buf),
                )
            2 -> EngineEvent.TrackEnded(
                FfiConverterString.read(buf),
                FfiConverterTypeEndReason.read(buf),
                )
            3 -> EngineEvent.GaplessTransition(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            4 -> EngineEvent.CrossfadeStarted(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterULong.read(buf),
                )
            5 -> EngineEvent.Buffering(
                FfiConverterOptionalString.read(buf),
                )
            6 -> EngineEvent.Ready(
                FfiConverterOptionalString.read(buf),
                )
            7 -> EngineEvent.StateChanged(
                FfiConverterTypePlaybackState.read(buf),
                )
            8 -> EngineEvent.QueueEnded
            9 -> EngineEvent.Error(
                FfiConverterTypeErrorKind.read(buf),
                FfiConverterString.read(buf),
                FfiConverterOptionalString.read(buf),
                )
            10 -> EngineEvent.DeviceChanged(
                FfiConverterOptionalTypeOutputDevice.read(buf),
                FfiConverterOptionalTypeOutputFormat.read(buf),
                )
            11 -> EngineEvent.Position(
                FfiConverterString.read(buf),
                FfiConverterDouble.read(buf),
                )
            12 -> EngineEvent.StreamTitle(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            13 -> EngineEvent.TransitionPlanned(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterULong.read(buf),
                FfiConverterULong.read(buf),
                FfiConverterULong.read(buf),
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: EngineEvent): ULong = when(value) {
        is EngineEvent.TrackStarted -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`itemId`)
                + FfiConverterUInt.allocationSize(value.`index`)
                + FfiConverterOptionalTypeTrackInfo.allocationSize(value.`info`)
            )
        }
        is EngineEvent.TrackEnded -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`itemId`)
                + FfiConverterTypeEndReason.allocationSize(value.`reason`)
            )
        }
        is EngineEvent.GaplessTransition -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`fromId`)
                + FfiConverterString.allocationSize(value.`toId`)
            )
        }
        is EngineEvent.CrossfadeStarted -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`fromId`)
                + FfiConverterString.allocationSize(value.`toId`)
                + FfiConverterULong.allocationSize(value.`durationMs`)
            )
        }
        is EngineEvent.Buffering -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterOptionalString.allocationSize(value.`itemId`)
            )
        }
        is EngineEvent.Ready -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterOptionalString.allocationSize(value.`itemId`)
            )
        }
        is EngineEvent.StateChanged -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypePlaybackState.allocationSize(value.`state`)
            )
        }
        is EngineEvent.QueueEnded -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is EngineEvent.Error -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeErrorKind.allocationSize(value.`kind`)
                + FfiConverterString.allocationSize(value.`message`)
                + FfiConverterOptionalString.allocationSize(value.`itemId`)
            )
        }
        is EngineEvent.DeviceChanged -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterOptionalTypeOutputDevice.allocationSize(value.`device`)
                + FfiConverterOptionalTypeOutputFormat.allocationSize(value.`format`)
            )
        }
        is EngineEvent.Position -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`itemId`)
                + FfiConverterDouble.allocationSize(value.`positionMs`)
            )
        }
        is EngineEvent.StreamTitle -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`itemId`)
                + FfiConverterString.allocationSize(value.`title`)
                + FfiConverterString.allocationSize(value.`url`)
            )
        }
        is EngineEvent.TransitionPlanned -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`fromId`)
                + FfiConverterString.allocationSize(value.`toId`)
                + FfiConverterULong.allocationSize(value.`startMs`)
                + FfiConverterULong.allocationSize(value.`entryMs`)
                + FfiConverterULong.allocationSize(value.`overlapMs`)
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
    }

    override fun write(value: EngineEvent, buf: ByteBuffer) {
        when(value) {
            is EngineEvent.TrackStarted -> {
                buf.putInt(1)
                FfiConverterString.write(value.`itemId`, buf)
                FfiConverterUInt.write(value.`index`, buf)
                FfiConverterOptionalTypeTrackInfo.write(value.`info`, buf)
                Unit
            }
            is EngineEvent.TrackEnded -> {
                buf.putInt(2)
                FfiConverterString.write(value.`itemId`, buf)
                FfiConverterTypeEndReason.write(value.`reason`, buf)
                Unit
            }
            is EngineEvent.GaplessTransition -> {
                buf.putInt(3)
                FfiConverterString.write(value.`fromId`, buf)
                FfiConverterString.write(value.`toId`, buf)
                Unit
            }
            is EngineEvent.CrossfadeStarted -> {
                buf.putInt(4)
                FfiConverterString.write(value.`fromId`, buf)
                FfiConverterString.write(value.`toId`, buf)
                FfiConverterULong.write(value.`durationMs`, buf)
                Unit
            }
            is EngineEvent.Buffering -> {
                buf.putInt(5)
                FfiConverterOptionalString.write(value.`itemId`, buf)
                Unit
            }
            is EngineEvent.Ready -> {
                buf.putInt(6)
                FfiConverterOptionalString.write(value.`itemId`, buf)
                Unit
            }
            is EngineEvent.StateChanged -> {
                buf.putInt(7)
                FfiConverterTypePlaybackState.write(value.`state`, buf)
                Unit
            }
            is EngineEvent.QueueEnded -> {
                buf.putInt(8)
                Unit
            }
            is EngineEvent.Error -> {
                buf.putInt(9)
                FfiConverterTypeErrorKind.write(value.`kind`, buf)
                FfiConverterString.write(value.`message`, buf)
                FfiConverterOptionalString.write(value.`itemId`, buf)
                Unit
            }
            is EngineEvent.DeviceChanged -> {
                buf.putInt(10)
                FfiConverterOptionalTypeOutputDevice.write(value.`device`, buf)
                FfiConverterOptionalTypeOutputFormat.write(value.`format`, buf)
                Unit
            }
            is EngineEvent.Position -> {
                buf.putInt(11)
                FfiConverterString.write(value.`itemId`, buf)
                FfiConverterDouble.write(value.`positionMs`, buf)
                Unit
            }
            is EngineEvent.StreamTitle -> {
                buf.putInt(12)
                FfiConverterString.write(value.`itemId`, buf)
                FfiConverterString.write(value.`title`, buf)
                FfiConverterString.write(value.`url`, buf)
                Unit
            }
            is EngineEvent.TransitionPlanned -> {
                buf.putInt(13)
                FfiConverterString.write(value.`fromId`, buf)
                FfiConverterString.write(value.`toId`, buf)
                FfiConverterULong.write(value.`startMs`, buf)
                FfiConverterULong.write(value.`entryMs`, buf)
                FfiConverterULong.write(value.`overlapMs`, buf)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





